INSERT INTO `candidates` VALUES (1,10,1,1,'Twelve years of service to the cooperative. I will push for transparent quarterly financial reporting and a members-first lending policy.',NULL,NULL,1,1,'2026-08-05 21:06:09'),(2,11,1,1,'Focus on expanding member benefits, digitising records, and reducing loan processing time from ten days to three.',NULL,NULL,2,1,'2026-08-05 21:06:09'),(3,12,2,1,'Strengthen coordination between committees and open monthly consultation sessions for ordinary members.',NULL,NULL,1,1,'2026-08-05 21:06:09'),(6,15,3,1,'Reduce operating overhead and channel the savings into the members\' dividend pool.',NULL,NULL,2,1,'2026-08-05 21:06:09'),(7,16,4,1,'Digitise every minute and resolution so members can search cooperative records from any device.',NULL,NULL,1,1,'2026-08-05 21:06:09'),(8,17,4,1,'Timely notices, accurate minutes, and a published calendar of all cooperative activities.',NULL,NULL,2,1,'2026-08-05 21:06:09'),(10,16,5,2,'Quarterly spot audits and a published compliance checklist.',NULL,NULL,2,1,'2026-08-05 21:06:09'),(15,21,13,1,'ughbhj','ughbhj',NULL,0,1,'2026-08-07 15:17:47');
/*!40000 ALTER TABLE `candidates` ENABLE KEYS */;
