INSERT INTO `elections` VALUES (1,'2026 Annual General Assembly Election','Election of officers for the 2026-2027 term. All members in good standing are entitled to one ballot.','2026-08-09 20:36:00','2026-08-10 20:36:00','published',NULL,NULL,2,'2026-08-05 21:06:09','2026-09-03 00:25:20'),(2,'Audit Committee Special Election','Special election to fill the vacant Audit Committee seats for the remainder of the term.','2026-08-07 14:51:00','2026-08-07 20:25:59','published',NULL,NULL,2,'2026-08-05 21:06:09','2026-09-03 00:25:23');
